css:
.pod-root * { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }
.pod-root { font-family: 'Pretendard', sans-serif; background: #070d18; color: #f8fafc; min-height: 100vh; padding: 32px 16px; display: flex; flex-direction: column; align-items: center; }
.pod-root .pod-container { width: 100%; max-width: 900px; }
.pod-root .pod-header { text-align: center; margin-bottom: 28px; }
.pod-root .pod-badge { display: inline-flex; align-items: center; gap: 6px; padding: 5px 12px; background: rgba(56,189,248,0.15); border: 1px solid rgba(56,189,248,0.4); border-radius: 9999px; font-size: 12px; font-weight: 800; color: #38bdf8; margin-bottom: 12px; }
.pod-root .pod-title { font-size: 26px; font-weight: 900; letter-spacing: -0.02em; color: #fff; margin-bottom: 8px; }
.pod-root .pod-desc { font-size: 14px; color: #94a3b8; }

.pod-root .calc-card { background: #0f182a; border: 1px solid rgba(255,255,255,0.08); border-radius: 28px; padding: 36px 32px; box-shadow: 0 20px 40px rgba(0,0,0,0.5); margin-bottom: 24px; }
.pod-root .grid-2col { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; }
@media (max-width: 768px) { .pod-root .grid-2col { grid-template-columns: 1fr; } .pod-root .calc-card { padding: 24px 20px; } }

.pod-root .city-select { width: 100%; padding: 14px 16px; background: rgba(255,255,255,0.04); border: 1.5px solid rgba(255,255,255,0.1); border-radius: 14px; color: #fff; font-size: 15px; font-weight: 700; outline: none; margin-bottom: 20px; }
.pod-root .city-select option { background: #0f182a; color: #fff; }

.pod-root .lifestyle-pill-group { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px; margin-bottom: 24px; }
.pod-root .lifestyle-btn { padding: 10px; border-radius: 10px; border: 1px solid rgba(255,255,255,0.1); background: rgba(255,255,255,0.03); color: #94a3b8; font-size: 12.5px; font-weight: 700; cursor: pointer; text-align: center; transition: all 0.2s; }
.pod-root .lifestyle-btn.active { border-color: #38bdf8; background: rgba(56,189,248,0.2); color: #fff; }

/* Result Box */
.pod-root .total-cost-box { background: rgba(0,0,0,0.3); border: 1px solid rgba(255,255,255,0.08); border-radius: 20px; padding: 24px; text-align: center; }
.pod-root .cost-won { font-size: 40px; font-weight: 900; color: #38bdf8; letter-spacing: -0.02em; margin: 8px 0 4px; }
.pod-root .cost-usd { font-size: 16px; font-weight: 700; color: #94a3b8; }

.pod-root .item-row { display: flex; justify-content: space-between; padding: 10px 0; border-bottom: 1px solid rgba(255,255,255,0.05); font-size: 13.5px; }
.pod-root .item-row span:last-child { font-weight: 800; color: #fff; }
.pod-root .btn-magnet { width: 100%; padding: 15px; background: #38bdf8; border: none; border-radius: 14px; font-size: 14px; font-weight: 900; color: #000; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 20px; transition: all 0.2s; }
.pod-root .btn-magnet:hover { background: #7dd3fc; transform: translateY(-1px); }
.pod-root{min-height:0;width:100%;max-width:100%;overflow-x:hidden;}

js:
var CITY_DATA = {
      bali: { rent: 950000, cowork: 220000, food: 520000, misc: 160000 },
      chiangmai: { rent: 550000, cowork: 150000, food: 380000, misc: 120000 },
      bangkok: { rent: 850000, cowork: 200000, food: 480000, misc: 180000 },
      tokyo: { rent: 1450000, cowork: 320000, food: 780000, misc: 250000 },
      lisbon: { rent: 1650000, cowork: 280000, food: 680000, misc: 220000 },
      danang: { rent: 480000, cowork: 140000, food: 320000, misc: 110000 }
    };

    var currentGrade = 'comfort';

    function setGrade(grade, el) {
      currentGrade = grade;
      document.querySelectorAll('.lifestyle-btn').forEach(b => b.classList.remove('active'));
      el.classList.add('active');
      updateCost();
    }

    function updateCost() {
      var cityKey = document.getElementById('selCity').value;
      var base = CITY_DATA[cityKey] || CITY_DATA['bali'];

      var mult = currentGrade === 'budget' ? 0.7 : (currentGrade === 'luxury' ? 1.6 : 1.0);

      var rent = Math.round(base.rent * mult);
      var cowork = Math.round(base.cowork * mult);
      var food = Math.round(base.food * mult);
      var misc = Math.round(base.misc * mult);

      var total = rent + cowork + food + misc;
      var usd = Math.round(total / 1380);

      document.getElementById('totalWon').innerText = '₩' + total.toLocaleString();
      document.getElementById('totalUsd').innerText = '약 $' + usd.toLocaleString() + ' / 월';

      document.getElementById('costRent').innerText = '₩' + rent.toLocaleString();
      document.getElementById('costCoworking').innerText = '₩' + cowork.toLocaleString();
      document.getElementById('costFood').innerText = '₩' + food.toLocaleString();
      document.getElementById('costMisc').innerText = '₩' + misc.toLocaleString();
    }

    document.getElementById('selCity').addEventListener('change', updateCost);
    updateCost();

    if (window.lucide) lucide.createIcons();

    if (window.MazaTelemetry) {
      window.MazaTelemetry.init({ podId: 'nomad' });
    }
